/** Original synthetic DEVELOPMENT material. No educator or curriculum validation. */
export const HYBRID_BENCHMARK_SUBJECTS = ['math', 'reading', 'english', 'science', 'history', 'computing'] as const
export const HYBRID_BENCHMARK_BANDS = ['middle_school', 'high_school', 'college_intro', 'college_advanced'] as const
export type HybridBenchmarkSubject = typeof HYBRID_BENCHMARK_SUBJECTS[number]
export type HybridBenchmarkBand = typeof HYBRID_BENCHMARK_BANDS[number]
export type HybridBenchmarkSourceStatus = 'sufficient' | 'missing' | 'conflicting'
export type HybridBenchmarkFocus = 'misconception' | 'missing_input' | 'evidence_conflict' | 'transfer'

export interface HybridBenchmarkInput {
  readonly targetSkill: string
  readonly taskType: string
  readonly problem: string
  readonly studentAttempt: string
  readonly sourceText?: string
}

export interface HybridBenchmarkCase {
  readonly id: string
  readonly subject: HybridBenchmarkSubject
  readonly band: HybridBenchmarkBand
  readonly provenance: {
    readonly kind: 'authored_synthetic'
    readonly rights: 'Original synthetic text; no external text or student data.'
  }
  readonly input: HybridBenchmarkInput
  readonly evaluation: {
    readonly sourceStatus: HybridBenchmarkSourceStatus
    readonly focus: HybridBenchmarkFocus
    readonly requiredKnownInputs: readonly string[]
    readonly requiredMissingInputs: readonly string[]
    readonly expectedTeachingAction: string
    readonly referenceAnswer: string
    readonly numericAnswer?: { readonly value: number; readonly unit: string; readonly tolerance: number }
    readonly rubric: {
      readonly accuracy: string
      readonly teaching: string
      readonly evidence: string
      readonly restraint: string
    }
    readonly disallowedMoves: readonly string[]
  }
}

export interface HybridBenchmarkModelInput extends HybridBenchmarkInput {
  readonly id: string
  readonly subject: HybridBenchmarkSubject
  readonly band: HybridBenchmarkBand
}

export const HYBRID_BENCHMARK_SCOPE = Object.freeze({
  version: 'hybrid-development-v1-draft',
  partition: 'development',
  cases: 96,
  educatorReviewed: false,
  representativeCurriculum: false,
  independentlyAudited: false,
  frozenForEvaluation: false,
  productionEligible: false,
} as const)

interface Seed {
  slug: string
  skill: string
  type: string
  problem: string
  attempt: string
  source?: string
  known: string[]
  missing?: string[]
  action: string
  answer: string
  numeric?: { value: number; unit: string; tolerance: number }
  criterion: string
  avoid: string[]
}

const scenarios: readonly [HybridBenchmarkSourceStatus, HybridBenchmarkFocus][] = [
  ['sufficient', 'misconception'], ['missing', 'missing_input'],
  ['conflicting', 'evidence_conflict'], ['sufficient', 'transfer'],
]

function cell(subject: HybridBenchmarkSubject, band: HybridBenchmarkBand, seeds: readonly Seed[]): HybridBenchmarkCase[] {
  if (seeds.length !== 4) throw new Error('Each development cell requires four authored cases')
  return seeds.map((seed, index) => {
    const [sourceStatus, focus] = scenarios[index]
    const missing = seed.missing ?? []
    return {
      id: `hybrid-dev-${subject}-${band}-${seed.slug}`, subject, band,
      provenance: { kind: 'authored_synthetic', rights: 'Original synthetic text; no external text or student data.' },
      input: { targetSkill: seed.skill, taskType: seed.type, problem: seed.problem,
        studentAttempt: seed.attempt, ...(seed.source === undefined ? {} : { sourceText: seed.source }) },
      evaluation: {
        sourceStatus, focus, requiredKnownInputs: seed.known, requiredMissingInputs: missing,
        expectedTeachingAction: seed.action, referenceAnswer: seed.answer,
        ...(seed.numeric === undefined ? {} : { numericAnswer: seed.numeric }),
        rubric: {
          accuracy: seed.criterion,
          teaching: seed.action,
          evidence: missing.length > 0
            ? `Preserve these known inputs: ${seed.known.join('; ')}. Explicitly identify what is not established: ${missing.join('; ')}.`
            : `Ground the reasoning in these supplied inputs: ${seed.known.join('; ')}. Treat proposed examples or checks as proposals.`,
          restraint: `Do not: ${seed.avoid.join('; ')}. Address the actual attempt calmly and leave the learner a concrete next operation.`,
        },
        disallowedMoves: seed.avoid,
      },
    }
  })
}

