function freezeDeep<T>(value: T): T {
  if (typeof value === 'object' && value !== null && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) freezeDeep(child)
    Object.freeze(value)
  }
  return value
}

export const HYBRID_BENCHMARK_CASES: readonly HybridBenchmarkCase[] = freezeDeep(authoredCases)

/** Allowlist projection: never serialize the full case or its evaluation to a provider. */
export function getHybridBenchmarkModelInput(caseOrId: HybridBenchmarkCase | string): HybridBenchmarkModelInput {
  const item = typeof caseOrId === 'string'
    ? HYBRID_BENCHMARK_CASES.find(candidate => candidate.id === caseOrId)
    : caseOrId
  if (!item) throw new Error('Unknown hybrid development case')
  return {
    id: item.id, subject: item.subject, band: item.band,
    targetSkill: item.input.targetSkill, taskType: item.input.taskType,
    problem: item.input.problem, studentAttempt: item.input.studentAttempt,
    ...(item.input.sourceText === undefined ? {} : { sourceText: item.input.sourceText }),
  }
}

/** User payload only. The separately frozen benchmark protocol supplies the system prompt. */
export function buildHybridBenchmarkUserPrompt(caseOrId: HybridBenchmarkCase | string): string {
  return JSON.stringify(getHybridBenchmarkModelInput(caseOrId), null, 2)
}
